using UnityEngine;
using RaveRacer.Rendering;
using RaveRacer.Vehicle.Customization;

namespace RaveRacer.Vehicle
{
    /// <summary>
    /// Automatically binds to the child sub-meshes of any Rave Racer vehicle model
    /// (`Chassis_Body`, `Wheel_FL`, `Wheel_FR`, `Wheel_RL`, `Wheel_RR`, `PopUp_L`, `PopUp_R`)
    /// generated by `generate_car_templates.py` or `generate_standalone_car_meshes.py`.
    /// Drives wheel spin, front steering, camber, body squat/roll, R4 drift yaw,
    /// Sleepy-Eye / Asymmetric "Wink" pop-up headlights, and Fluid Race Color updates.
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class VehicleVisualRigController : MonoBehaviour
    {
        [Header("Vibe Palette & Shader Binding")]
        public VibePaletteSO initialVibePalette;
        [Range(0f, 1f)] public float vibeRowBlend = 0f;

        [Header("Auto-Discovered Sub-Mesh Transforms")]
        public Transform visualChassis;
        public Transform wheelFL;
        public Transform wheelFR;
        public Transform wheelRL;
        public Transform wheelRR;
        public Transform popUpHeadlightL;
        public Transform popUpHeadlightR;

        [Header("Wheel & Stance Tuning")]
        public float wheelRadius = 0.34f;
        public float maxSteerAngleDeg = 32f;
        public float frontCamberDeg = -3.0f;
        public float rearCamberDeg = -2.5f;

        [Header("Pop-Up Headlights (Supports Sleepy-Eye & FC3S Asymmetric Wink)")]
        public bool useAsymmetricWinkAngles = false;
        [Range(0f, 45f)] public float popUpOpenAngleDeg = 22f;
        [Range(0f, 45f)] public float popUpLeftOpenAngleDeg = 22f;
        [Range(0f, 45f)] public float popUpRightOpenAngleDeg = 22f;

        [Header("R4 Arcade Body Pitch, Roll & Drift Yaw")]
        public float maxDriftYawDeg = 28f;
        public float maxBodyRollDeg = 4.5f;
        public float maxAccelPitchDeg = 2.5f;
        public float visualSmoothing = 14f;

        private float _wheelSpinAngleDeg;
        private float _currentSteerDeg;
        private Quaternion _baseChassisRotation = Quaternion.identity;
        private MaterialPropertyBlock _mpb;
        private Renderer[] _renderers;
        private CarCustomizationController _customizationController;

        private static readonly int VibeLutId = Shader.PropertyToID("_VibeLUT");
        private static readonly int VibeRowBlendId = Shader.PropertyToID("_VibeRowBlend");

        private void Reset()
        {
            AutoBindHierarchy();
        }

        private void Awake()
        {
            AutoBindHierarchy();
            if (visualChassis != null)
                _baseChassisRotation = visualChassis.localRotation;

            _mpb = new MaterialPropertyBlock();
            _renderers = GetComponentsInChildren<Renderer>(true);
            _customizationController = GetComponent<CarCustomizationController>();
            ApplyVibePalette(initialVibePalette, vibeRowBlend);
        }

        /// <summary>
        /// Automatically locates the sub-meshes named by our Blender and Standalone OBJ generators.
        /// </summary>
        [ContextMenu("Auto-Bind Vehicle Hierarchy")]
        public void AutoBindHierarchy()
        {
            if (visualChassis == null)
                visualChassis = FindChildRecursive(transform, "VisualChassis") ?? transform;

            wheelFL = FindChildRecursive(transform, "Wheel_FL");
            wheelFR = FindChildRecursive(transform, "Wheel_FR");
            wheelRL = FindChildRecursive(transform, "Wheel_RL");
            wheelRR = FindChildRecursive(transform, "Wheel_RR");
            popUpHeadlightL = FindChildRecursive(transform, "PopUp_L");
            popUpHeadlightR = FindChildRecursive(transform, "PopUp_R");
        }

        /// <summary>
        /// Configures the Left and Right pop-up headlight hinge angles for Fixed, Sleepy-Eye,
        /// Full Open, or Asymmetric "Wink" (`Cars/08` RX-7 FC3S) modes.
        /// </summary>
        public void ApplyHeadlightStyle(HeadlightStyle style, float customLeftDeg = 22f, float customRightDeg = 22f)
        {
            switch (style)
            {
                case HeadlightStyle.PopUp_DualFullOpen:
                    useAsymmetricWinkAngles = false;
                    popUpOpenAngleDeg = 42f;
                    popUpLeftOpenAngleDeg = 42f;
                    popUpRightOpenAngleDeg = 42f;
                    break;
                case HeadlightStyle.PopUp_SleepyEye:
                    useAsymmetricWinkAngles = false;
                    popUpOpenAngleDeg = 22f;
                    popUpLeftOpenAngleDeg = 22f;
                    popUpRightOpenAngleDeg = 22f;
                    break;
                case HeadlightStyle.PopUp_WinkLeftOpen:
                    useAsymmetricWinkAngles = true;
                    popUpLeftOpenAngleDeg = customLeftDeg > 1f ? customLeftDeg : 42f;
                    popUpRightOpenAngleDeg = 0f;
                    break;
                case HeadlightStyle.PopUp_WinkRightOpen:
                    useAsymmetricWinkAngles = true;
                    popUpLeftOpenAngleDeg = 0f;
                    popUpRightOpenAngleDeg = customRightDeg > 1f ? customRightDeg : 42f;
                    break;
                default:
                    useAsymmetricWinkAngles = true;
                    popUpLeftOpenAngleDeg = customLeftDeg;
                    popUpRightOpenAngleDeg = customRightDeg;
                    break;
            }

            UpdatePopUpHeadlightTransforms();
        }

        /// <summary>
        /// Updates wheel rotations, steering, camber, chassis drift/pitch/roll,
        /// pop-up headlights, and fluid race color state every frame.
        /// </summary>
        public void UpdateVisualRig(
            float forwardSpeedMetersPerSec,
            float steerInput,
            float driftSlipNormalized,
            float accelNormalized,
            float rageNormalized = 0f,
            float cockinessNormalized = 0f)
        {
            float dt = Time.deltaTime;

            // 1. Accumulate wheel spin angle from linear velocity
            float angularVelDeg = (forwardSpeedMetersPerSec / Mathf.Max(wheelRadius, 0.05f)) * Mathf.Rad2Deg;
            _wheelSpinAngleDeg = Mathf.Repeat(_wheelSpinAngleDeg + angularVelDeg * dt, 360f);

            // 2. Smooth steering angle (counter-steers during drift)
            float targetSteer = Mathf.Clamp(steerInput - driftSlipNormalized * 0.65f, -1f, 1f) * maxSteerAngleDeg;
            _currentSteerDeg = Mathf.Lerp(_currentSteerDeg, targetSteer, dt * visualSmoothing);

            ApplyWheelRotation(wheelFL, _wheelSpinAngleDeg, _currentSteerDeg,  frontCamberDeg);
            ApplyWheelRotation(wheelFR, _wheelSpinAngleDeg, _currentSteerDeg, -frontCamberDeg);
            ApplyWheelRotation(wheelRL, _wheelSpinAngleDeg, 0f,               rearCamberDeg);
            ApplyWheelRotation(wheelRR, _wheelSpinAngleDeg, 0f,              -rearCamberDeg);

            // 3. Chassis pitch (squat/dive), roll (corner lean), and R4 drift yaw offset
            if (visualChassis != null && visualChassis != transform)
            {
                float pitch = -accelNormalized * maxAccelPitchDeg;
                float roll = steerInput * maxBodyRollDeg;
                float yaw = driftSlipNormalized * maxDriftYawDeg;
                Quaternion targetRot = _baseChassisRotation * Quaternion.Euler(pitch, yaw, roll);
                visualChassis.localRotation = Quaternion.Slerp(visualChassis.localRotation, targetRot, dt * visualSmoothing);
            }

            // 4. Sleepy-Eye & Asymmetric "Wink" Pop-Up Headlights
            UpdatePopUpHeadlightTransforms();

            // 5. Drive Fluid Individual Color Shifting if a CarCustomizationController is attached
            if (_customizationController != null)
            {
                _customizationController.UpdateFluidRaceShaderState(
                    vibeRowBlend,
                    driftSlipNormalized,
                    rageNormalized,
                    cockinessNormalized
                );
            }
        }

        private void UpdatePopUpHeadlightTransforms()
        {
            float leftDeg = useAsymmetricWinkAngles ? popUpLeftOpenAngleDeg : popUpOpenAngleDeg;
            float rightDeg = useAsymmetricWinkAngles ? popUpRightOpenAngleDeg : popUpOpenAngleDeg;

            if (popUpHeadlightL != null)
                popUpHeadlightL.localRotation = Quaternion.Euler(-leftDeg, 0f, 0f);
            if (popUpHeadlightR != null)
                popUpHeadlightR.localRotation = Quaternion.Euler(-rightDeg, 0f, 0f);
        }

        public void ApplyVibePalette(VibePaletteSO palette, float rowBlend)
        {
            initialVibePalette = palette;
            vibeRowBlend = Mathf.Clamp01(rowBlend);
            if (_renderers == null || _mpb == null)
                return;

            foreach (Renderer r in _renderers)
            {
                r.GetPropertyBlock(_mpb);
                if (palette != null && palette.lutTexture != null)
                    _mpb.SetTexture(VibeLutId, palette.lutTexture);
                _mpb.SetFloat(VibeRowBlendId, vibeRowBlend);
                r.SetPropertyBlock(_mpb);
            }

            if (_customizationController != null)
            {
                _customizationController.UpdateFluidRaceShaderState(
                    vibeRowBlend,
                    _customizationController.driftChromaticIntensity,
                    _customizationController.boilingRageIntensity,
                    _customizationController.untouchableCockinessIntensity
                );
            }
        }

        private static void ApplyWheelRotation(Transform wheel, float spinDeg, float steerDeg, float camberDeg)
        {
            if (wheel == null)
                return;
            wheel.localRotation = Quaternion.Euler(spinDeg, steerDeg, camberDeg);
        }

        private static Transform FindChildRecursive(Transform parent, string exactName)
        {
            if (parent.name == exactName)
                return parent;
            for (int i = 0; i < parent.childCount; i++)
            {
                Transform found = FindChildRecursive(parent.GetChild(i), exactName);
                if (found != null)
                    return found;
            }
            return null;
        }
    }
}
